P = Path(__file__).resolve().parents[1]
ROOT = P.parents[1]
RAW = ROOT / 'output/imagegen/warlord/ew6_v025'
CLI = Path('C:/Users/carzy/.codex/skills/sub2-image-gen/scripts/sub2_image_gen.py')
STYLE = '''Original premium historical strategy game art for 1920-1924 Republican China.
Visual direction: the clearly readable elevated 2.5D miniature-map language of European War 6,
but entirely original Chinese period subjects, never copied game assets or logos.
Rich natural olive and meadow green, slate-gray stone, navy-blue shadows, warm light highlights;
clean hand-painted volumes, subtle realistic material, very clear coherent silhouettes.
Camera 60 degrees above the ground, north-up map, upper-left sunlight and soft lower-right shadows.
Restrained fine dark contours, NOT old yellow parchment, monochrome engraving or noisy ink hatching.
Not photorealism, anime, plastic, fantasy or neon. NO lettering, watermark or UI on runtime assets.
'''


def plan():
    jobs = []
    for name in list(EQUIPMENT) + ['elite_assault', 'elite_cavalry', 'elite_artillery']:
        base = {'elite_assault':'assault','elite_cavalry':'cavalry','elite_artillery':'field_artillery'}.get(name,name)
        for facing in ('se','sw'):
            direction = 'bottom right (southeast)' if facing=='se' else 'bottom left (southwest)'
            prompt = STYLE + f'''One compact map figurine formation: {EQUIPMENT[base]}.
All face {direction}; simplified complete bodies viewed from above, three readable figures at most.
Separate silhouettes with space between individual soldiers, three-dimensional hand-painted volume.
Khaki or gray-blue plain high-collar tunics, UNMARKED plain peaked caps, leather belts and puttees.
Tiny heads, visible equipment, slate steel gun barrels, brown wooden rifle stocks or gun wheels.
Equipment must fit early 1920s; no modern rifles, WWII helmets, tanks, medals, insignia or flags.
Compose a low wide 1.3:1 silhouette in the central 78% of a square canvas. Full rifles, sabres, horses,
gun wheels and tails inside generous empty margins; clear at 76px width. Transparent alpha outside.
NO landscape, ground disc, pedestal, checkerboard, sheet or separate views.
'''
            jobs.append(('unit','unit_'+name+'_'+facing,prompt,True))
    jobs += [
        ('tile','tile_plain_01',STYLE+'''One opaque seamless top-down flat natural lowland meadow material,
base sage green #B4BD91, quiet broad hand-painted variations, subtle tiny yellow-green dry grass marks.
Large quiet areas, no trees, objects, grid, rocks, mapped fields, rivers, roads or geographic outlines.
No beige paper, ink spots or high-frequency noise. Texture only, edges join seamlessly.''',False),
        ('tile','tile_sea_01',STYLE+'''One opaque seamless top-down calm teal-blue sea material,
base blue #428397, softly varied deeper #32677D water with extremely fine quiet short wave strokes.
Stylized painted strategy-map water, no shore, foam clumps, ships, islands, grid or frame.
Uniform calm lighting, continuous edges, no mottled photographic noise.''',False),
    ]
    # r001 returned a scene rather than a sea material. Preserve that rejected
    # source and give the replacement an unambiguous material-only instruction.
    jobs[33]=('tile','tile_sea_01','''ONLY A BLUE WATER TEXTURE. One flat seamless square of calm
teal-blue ocean water, top-down, entire canvas water edge to edge. A quiet painted material for
a strategy game. Deep turquoise #428397, subtly lighter short wave strokes. No coastline, land,
islands, terrain, buildings, mountains, soldiers, objects, scene, map, borders, text or UI.
Opaque square, uniform low contrast, evenly illuminated, seamless texture. Nothing except water.''',False)
    for i,subject in enumerate(['a connected broad ridge with three weathered craggy peaks','a connected asymmetric rocky ridge with a tall peak and narrow saddle','a connected wide irregular fan of four rocky peaks','a connected steep ridge with layered foothill shoulders'],1):
        jobs.append(('scenery','scenery_atlas_ridge_%02d'%i,STYLE+f'''ONE terrain relief patch: {subject}.
Northern Chinese mountains. Sculptural hand-painted gray-green rock faces, clear light-facing planes,
slate-blue shadow faces, gently green grassy lower slopes, readable shape rather than tiny black lines.
Wide 2:1 connected mass, no skyline or distant backdrop, no trees, snow, roads, buildings or water.
Transparent alpha around soft irregular silhouette. NO beige/yellow foothill paper halo or square base.
Center entire patch in 80% of canvas, very legible at 220px width.''',True))
    for i,subject in enumerate(['a low connected gently rolling hill with three soft shoulders','a broad low rocky foothill with a shallow central saddle'],1):
        jobs.append(('scenery','scenery_atlas_hill_%02d'%i,STYLE+f'''ONE low connected relief patch: {subject}.
Green natural slopes, restrained slate rock faces, light volume, wide low 2:1 shape, transparent exterior.
No beige paper halo, trees, scenery, roads, geographic labels, grid or square background.''',True))
    towns = {
        'scenery_station_town':'a compact Chinese railway station group circa 1920: low gray-brick station house, timber platform canopy, six gray-tiled courtyard houses, telegraph poles, no track or train',
        'scenery_walled_city':'a compact Chinese walled town circa 1920: low gray-brick wall, one restrained city gate tower, eight tiled-roof courtyard blocks, no fantasy castle or imperial palace',
        **SUBJECTS,
    }
    for name,subject in towns.items():
        jobs.append(('scenery',name,STYLE+'One coherent small elevated isometric map settlement: '+subject+'''.
Blue-gray tiled roofs with light planes, warm gray walls, pale brick edges, dimensional strong shadow.
Low wide 1.4:1 compact silhouette, complete building group centered in 78% canvas, no isolated detached
props. Transparent alpha around the buildings, no ground square, landscape, border or invented landmark.
Must remain beautiful and legible at 100px width, do not drown roof shapes in fine black hatching.''',True))
    for name,subject in [
        ('ui_steel_panel','a clean rectangular blue-black brushed steel command panel with a narrow silver beveled outer rim and restrained dark bronze inner pinstripe'),
        ('ui_button_plate','a clean horizontal dark slate steel button plate with thin silver bevel and discreet bronze edge'),
    ]:
        jobs.append(('ui',name,STYLE+'''ONE opaque rectangular interface material, front-on flat view.
'''+subject+'''. Extremely low-detail quiet dark center suitable for readable text, uniformly straight
edges, no screws, symbols, text, rust stains or decorative illustrations. Fill complete image; no alpha.
No tiled montage, icons or nested panels. Texture will be used by a native nine-patch control.''',False))
    jobs.append(('background','background_battle_field',STYLE+'''One full-width coherent battlefield stage
for a short native combat vignette. Northern Chinese open ground in 1924 near low gray rocky foothills.
Layered pale green foreground earth, muted olive middle ground, hazy slate-green distant mountains,
soft pale blue morning sky. No soldiers, weapons, buildings, landmarks, forest or flags.
Quiet center and empty lower 60% for independent animated troop sprites. Single painted landscape,
no panels, no lettering, no frame, no hex grid. Wide landscape composition.''',False))
    for name,subject in [('fx_muzzle','one small bright yellow-orange rifle muzzle flash with a few short sparks'),('fx_cannon_blast','one compact period shell impact with gray smoke and restrained orange fire'),('fx_bullet_hit','one small dusty battlefield bullet impact with flying earth'),('fx_capture','one elegant small warm gold radial victory light burst')]:
        jobs.append(('fx',name,STYLE+'ONE independent effect sprite: '+subject+'''. Transparent exterior,
no background, unit, terrain, stars, text, ground disc or border. Center in 70% canvas, clean readable
shape at small size. Not a sheet. Smoke softly translucent, no giant fantasy magic explosion.''',True))
    return jobs


def generate(job):
    category,name,prompt,transparent = job
    revision='r002' if name=='tile_sea_01' else 'r001'
    folder=RAW/name/revision;folder.mkdir(parents=True,exist_ok=True)
    prompt_file=folder/'prompt.txt';source=folder/'source.png'
    if prompt_file.exists() and prompt_file.read_text(encoding='utf-8')!=prompt:
        raise RuntimeError('Immutable prompt differs: '+name)
    if not prompt_file.exists():prompt_file.write_text(prompt,encoding='utf-8')
    if not source.exists():
        log_file=folder/'generation.log'
        attempt=2
        while log_file.exists():
            log_file=folder/('generation_attempt_%02d.log'%attempt);attempt+=1
        with log_file.open('w',encoding='utf-8') as log:
            result=subprocess.run([sys.executable,str(CLI),'generate','--model','gpt-image-2.5','--quality','high','--size','1024x1024','--background','transparent' if transparent else 'opaque','--prompt-file',str(prompt_file),'--out',str(source)],stdout=log,stderr=subprocess.STDOUT,timeout=900)
        if result.returncode or not source.exists():raise RuntimeError('Sub2 generation failed: '+name)
    with Image.open(source) as im:
        dimensions=list(im.size);alpha=im.getchannel('A').getextrema()[0] if im.mode=='RGBA' else 255
    if transparent and alpha!=0:raise RuntimeError('Transparent alpha missing: '+name)
    dest=P/'assets'/category/(name+'.png');dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(source,dest)
    sha=lambda file:hashlib.sha256(file.read_bytes()).hexdigest()
    return dict(id=name,category=category,subject=name,view=name.rsplit('_',1)[-1],state='generated_pending_visual_review',game_ready=False,source_kind='sub2_image_gen',model='gpt-image-2.5',quality='high',style_version='warlord_ew6_v025',era='1920-1924',source_file=source.relative_to(ROOT).as_posix(),source_sha256=sha(source),prompt_file=prompt_file.relative_to(ROOT).as_posix(),prompt_sha256=sha(prompt_file),actual_dimensions=dimensions,planned_source_request=[1024,1024],engine_path='res://'+dest.relative_to(P).as_posix(),planned_engine_path='res://'+dest.relative_to(P).as_posix(),runtime_import_max_dimension=512 if category in ['unit','scenery','fx'] else 1024,background='transparent' if transparent else 'tileable_or_scene_specific',alpha_min=alpha,revision='ew6_v025_'+revision,image_modified=False)


def main():
    ap=argparse.ArgumentParser();ap.add_argument('--workers',type=int,default=2);ap.add_argument('--pilot',action='store_true');ap.add_argument('--only');args=ap.parse_args()
    jobs=plan()
    if args.only:jobs=[job for job in jobs if job[1] in args.only.split(',')]
    if args.pilot:
        names={'tile_plain_01','tile_sea_01','scenery_atlas_ridge_01','scenery_atlas_hill_01','scenery_walled_city','unit_rifle_se','unit_cavalry_se','unit_machine_gun_se','unit_field_artillery_se','ui_steel_panel','background_battle_field'}
        jobs=[job for job in jobs if job[1] in names]
    path=P/'assets/manifest.json';manifest=json.loads(path.read_text(encoding='utf-8'));records={row['id']:row for row in manifest['assets']};done=[];failures=[]
    # Terrain is installed first so runtime inspection can begin during generation.
    jobs.sort(key=lambda job: {'tile':0,'scenery':1,'ui':2,'background':3,'fx':4,'unit':5}[job[0]])
    with ThreadPoolExecutor(max_workers=args.workers) as pool:
        futures={pool.submit(generate,job):job[1] for job in jobs}
        for future in as_completed(futures):
            try:record=future.result()
            except Exception as error:
                failures.append(dict(id=futures[future],reason=str(error)));print(json.dumps(failures[-1]),flush=True);continue
            records[record['id']]=record;done.append(record['id']);manifest['assets']=sorted(records.values(),key=lambda row:row['id'])
            path.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
            print(record['id']+': original Sub2 PNG installed',flush=True)
    (P/'reports/ew6_asset_generation.json').write_text(json.dumps(dict(passed=not failures,requested=len(jobs),completed=done,failures=failures,provider='sub2-image-gen/gpt-image-2.5',manual_compositing=False,source_images_modified=False),indent=2),encoding='utf-8')
    raise SystemExit(bool(failures))


if __name__=='__main__':main()
